    write_new(BASE/'expected-final.json',{'states':states,'final_media':media,
        'media_evidence':['evaluation/task07/capture/final-verification-v2/verification.json','evaluation/task07/capture/FINAL_REVIEW.md','evaluation/task07/editorial/FINAL_REVIEW.md']})
